// test_vectors.cpp -- the cross-implementation check.
//
// doc/vectors.txt is generated by `cargo test -p qd-core` (qd-core/tests/wire_vectors.rs).
// This test rebuilds the SAME samples with the NATIVE encoder and compares the bytes.
//
// WHY THIS TEST EXISTS
// --------------------
// The wire format has two independent implementations: one in Rust (the relay and the
// canonical encoder) and one in C++ (the DLL).  A format that only one side implements
// drifts silently, and a round-trip test inside either implementation passes for a
// symmetric bug.  Binding both to a checked-in byte file means a change to either side
// fails a test here rather than producing a session where the peer's position is
// garbage and nothing logs why.
//
// The samples are the ones the Rust test uses; they are reproduced below rather than
// parsed, because parsing them would let a drift in the sample definition hide inside
// the comparison.
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#include "qdwire.h"

static int g_pass = 0;
static int g_fail = 0;
static int g_missing = 0;

#define CHECK(cond, name)                                                          \
    do {                                                                           \
        if (cond) { ++g_pass; }                                                    \
        else { ++g_fail; printf("FAIL %s  (%s:%d)\n", name, __FILE__, __LINE__); } \
    } while (0)

using namespace qd::wire;

// ---- the file -------------------------------------------------------------
static char  g_lines[64][512];
static int   g_lineCount = 0;
static const char* g_pathUsed = "";

static bool LoadVectors()
{
    // The test may be run from test\, test\build\ or the repo root, so try each.
    static const char* candidates[] = {
        "doc/vectors.txt",
        "../doc/vectors.txt",
        "../../doc/vectors.txt",
        "G:/Freespace/Queens_Domain/mod/doc/vectors.txt",
    };
    for (int i = 0; i < 4; ++i) {
        FILE* f = fopen(candidates[i], "r");
        if (!f) continue;
        g_pathUsed = candidates[i];
        g_lineCount = 0;
        while (g_lineCount < 64 && fgets(g_lines[g_lineCount], sizeof(g_lines[0]), f)) {
            ++g_lineCount;
        }
        fclose(f);
        return true;
    }
    return false;
}

// "<name> | <hex bytes>"
static int FindVector(const char* name, uint8_t* out, int cap)
{
    size_t nameLen = strlen(name);
    for (int i = 0; i < g_lineCount; ++i) {
        const char* l = g_lines[i];
        if (l[0] == '#' || l[0] == '\n' || l[0] == 0) continue;
        if (strncmp(l, name, nameLen) != 0) continue;
        const char* p = l + nameLen;
        while (*p == ' ') ++p;
        if (*p != '|') continue;
        ++p;
        int n = 0;
        while (*p && n < cap) {
            while (*p == ' ' || *p == '\t') ++p;
            if (!((*p >= '0' && *p <= '9') || (*p >= 'a' && *p <= 'f') || (*p >= 'A' && *p <= 'F'))) break;
            char hex[3] = { p[0], p[1], 0 };
            out[n++] = (uint8_t)strtoul(hex, nullptr, 16);
            p += 2;
        }
        return n;
    }
    ++g_missing;
    printf("MISSING  %s (not in %s)\n", name, g_pathUsed);
    return -1;
}

static void Compare(const char* name, const uint8_t* got, int gotLen)
{
    uint8_t want[512];
    int wantLen = FindVector(name, want, sizeof(want));
    if (wantLen < 0) return;

    // doc/vectors.txt prefixes each line with the envelope `kind` byte and excludes
    // the rest of the envelope (WIRE.md section 1).  Our buffers hold bodies only, so
    // the kind is checked for plausibility here and the body compared below.  The
    // kind/body split itself is asserted exactly by test_wire.cpp's envelope test.
    if (wantLen < 1) {
        ++g_fail;
        printf("FAIL %s  empty vector\n", name);
        return;
    }
    uint8_t kind = want[0];
    bool kindKnown = (kind >= 0x01 && kind <= 0x04) ||
                     (kind >= 0x10 && kind <= 0x14) ||
                     (kind >= 0x20 && kind <= 0x22) ||
                     (kind == 0x30);
    if (!kindKnown) {
        ++g_fail;
        printf("FAIL %s  unknown kind byte 0x%02X\n", name, kind);
        return;
    }
    const uint8_t* wantBody = want + 1;
    int wantBodyLen = wantLen - 1;

    if (gotLen != wantBodyLen) {
        ++g_fail;
        printf("FAIL %s  body length %d, vector says %d\n", name, gotLen, wantBodyLen);
        return;
    }
    for (int i = 0; i < gotLen; ++i) {
        if (got[i] != wantBody[i]) {
            ++g_fail;
            printf("FAIL %s  first difference at body byte %d\n  native :", name, i);
            for (int k = 0; k < gotLen; ++k) printf(" %02X", got[k]);
            printf("\n  vector :");
            for (int k = 0; k < wantBodyLen; ++k) printf(" %02X", wantBody[k]);
            printf("\n");
            return;
        }
    }
    ++g_pass;
}

// ---- samples, mirroring qd-core/tests/wire_vectors.rs ---------------------
static const char* kLevel = "/Game/Maps/Coop";
static const char* kItemKey = "/Game/Items/KeyItems/AquaDoorKey_2.AquaDoorKey_2";
static const char* kItemLamp = "/Game/Items/Tools/Lamp.Lamp";
static const char* kCheckpoint = "/Game/Maps/Coop:PlayerStart_1";

static void TestAll()
{
    uint8_t buf[512];

    // hello: proto, build_hash, role_wanted, level, name
    {
        Writer w(buf, sizeof(buf));
        w.U8(1);
        w.U32(0x11223344u);
        w.U8(2);
        w.Str(kLevel);
        w.Str("Player2");
        Compare("hello", buf, w.len);
    }

    // welcome: role, session, host_tick, level, flags_rev
    {
        Writer w(buf, sizeof(buf));
        w.U8(1);
        w.U32(7);
        w.U32(123456);
        w.Str(kLevel);
        w.U32(42);
        Compare("welcome", buf, w.len);
    }

    // keepalive: empty body
    Compare("keepalive", buf, 0);

    // ack: seq
    {
        Writer w(buf, sizeof(buf));
        w.U32(258);
        Compare("ack", buf, w.len);
    }

    // player_row
    {
        PlayerRow r;
        memset(&r, 0, sizeof(r));
        r.slot = 1;
        r.sample_ms = 1500;
        r.px = 1000; r.py = -2000; r.pz = 300;
        r.yaw = 8192; r.pitch = -4096;
        r.vx = 100; r.vy = -100; r.vz = 0;
        r.move_mode = 3;
        r.action = 1;
        r.flags = 5;
        Writer w(buf, sizeof(buf));
        WritePlayer(w, r);
        Compare("player_row", buf, w.len);
    }

    // world_flags
    {
        FlagEntry e[2];
        e[0].name = "CheckpointReached"; e[0].value = 7;
        e[1].name = "DoorA";             e[1].value = 1;
        Writer w(buf, sizeof(buf));
        WriteFlagsHeader(w, 5, 2);
        WriteFlagsChunk(w, e, 2, 0, 5);
        Compare("world_flags", buf, w.len);
    }

    // actor_states
    {
        ActorState a;
        a.guid[0] = 0x03020100u;
        a.guid[1] = 0x07060504u;
        a.guid[2] = 0x0b0a0908u;
        a.guid[3] = 0x0f0e0d0cu;
        a.value = -1;
        Writer w(buf, sizeof(buf));
        WriteActorStatesHeader(w, 9, 1);
        WriteActorStatesChunk(w, &a, 1, 0);
        Compare("actor_states", buf, w.len);
    }

    // inventory
    {
        Writer w(buf, sizeof(buf));
        WriteInventoryHeader(w, 3, 2);
        WriteInventoryEntry(w, kItemKey, 1);
        WriteInventoryEntry(w, kItemLamp, 4);
        Compare("inventory", buf, w.len);
    }

    // enemy_rows
    {
        EnemyRow e[2];
        memset(e, 0, sizeof(e));
        e[0].guid[0] = 0x03020100u; e[0].guid[1] = 0x07060504u;
        e[0].guid[2] = 0x0b0a0908u; e[0].guid[3] = 0x0f0e0d0cu;
        e[0].px = 100; e[0].py = -200; e[0].pz = 50;
        e[0].yaw = 16384; e[0].hp = 80; e[0].flags = 7;

        e[1].guid[0] = 0x13121110u; e[1].guid[1] = 0x17161514u;
        e[1].guid[2] = 0x1b1a1918u; e[1].guid[3] = 0x1f1e1d1cu;
        e[1].px = -300; e[1].py = 400; e[1].pz = -25;
        e[1].yaw = -16384; e[1].hp = 0; e[1].flags = 2;

        Writer w(buf, sizeof(buf));
        WriteEnemyHeader(w, 2);
        WriteEnemyChunk(w, e, 2, 0);
        Compare("enemy_rows", buf, w.len);
    }

    // intents
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_SET_FLAG, 5);
        w.Str("DoorA");
        w.I32(1);
        w.U8(1);
        Compare("intent_set_flag", buf, w.len);
    }
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_GRANT_ITEM, 6);
        w.Str(kItemLamp);
        w.I32(2);
        Compare("intent_grant_item", buf, w.len);
    }
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_CONSUME_ITEM, 7);
        w.Str(kItemKey);
        w.I32(1);
        Compare("intent_consume_item", buf, w.len);
    }
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_DIALOGUE_ANS, 8);
        const uint32_t g[4] = { 0x03020100u, 0x07060504u, 0x0b0a0908u, 0x0f0e0d0cu };
        w.Guid(g);
        w.U16(3);
        w.U16(1);
        Compare("intent_dialogue_answer", buf, w.len);
    }
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_CHECKPOINT, 9);
        w.Str(kCheckpoint);
        Compare("intent_checkpoint", buf, w.len);
    }
    {
        Writer w(buf, sizeof(buf));
        WriteIntentHeader(w, I_ACTOR_STATE, 10);
        const uint32_t g[4] = { 0x03020100u, 0x07060504u, 0x0b0a0908u, 0x0f0e0d0cu };
        w.Guid(g);
        w.I32(42);
        Compare("intent_actor_state", buf, w.len);
    }

    // dialogue_state
    {
        DialogueBody d;
        memset(&d, 0, sizeof(d));
        d.seq = 4;
        d.npc[0] = 0x03020100u; d.npc[1] = 0x07060504u;
        d.npc[2] = 0x0b0a0908u; d.npc[3] = 0x0f0e0d0cu;
        d.slot = 1;
        d.line = 12;
        d.entry = 3;
        Writer w(buf, sizeof(buf));
        WriteDialogue(w, d);
        Compare("dialogue_state", buf, w.len);
    }

    // level_union: bits_len(2), bits{0x05,0x02}, has_names=1, n=3, names
    {
        Writer w(buf, sizeof(buf));
        WriteLevelUnionHeader(w, 2);
        w.U8(0x05);
        w.U8(0x02);
        WriteLevelUnionNamesFlag(w, 1);
        w.U16(3);
        w.Str("L_Main");
        w.Str("L_Dungeon");
        w.Str("L_Boss");
        Compare("level_union", buf, w.len);
    }
    // level_union_steady: same bits, no name table
    {
        Writer w(buf, sizeof(buf));
        WriteLevelUnionHeader(w, 2);
        w.U8(0x05);
        w.U8(0x02);
        WriteLevelUnionNamesFlag(w, 0);
        Compare("level_union_steady", buf, w.len);
    }

    // log
    {
        Writer w(buf, sizeof(buf));
        w.Bytes("hello from host", 15);
        Compare("log", buf, w.len);
    }
}

int main()
{
    printf("=== wire vector cross-check (native vs qd-core) ===\n");
    if (!LoadVectors()) {
        printf("FAIL  could not open doc/vectors.txt from any known path\n");
        printf("      run: cargo test -p qd-core   (it regenerates the file)\n");
        return 1;
    }
    printf("      vectors: %s (%d lines)\n", g_pathUsed, g_lineCount);

    TestAll();

    printf("=== %d matched, %d failed, %d missing ===\n", g_pass, g_fail, g_missing);
    // A missing vector is a failure too: it means the Rust side stopped emitting a
    // body the native side still sends, which is a silent incompatibility.
    if (g_missing > 0) return 1;
    return g_fail == 0 ? 0 : 1;
}

